21:body{background:var(--bg);color:var(--ink);font:15px/1.6 var(--f-body);
24:h1,h2,h3{font-family:var(--f-display);font-weight:600;line-height:1.1;text-wrap:balance;margin:0}
25:h1{font-size:46px} h2{font-size:30px} h3{font-size:24px}
29:.eyebrow{font:500 12px/1 var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--accent)}
30:.lead{font-size:18px;max-width:66ch}
31:.note{font-size:13px;color:var(--muted)}
34:table{border-collapse:collapse;width:100%;font-size:14px}
36:th{font:500 12px/1.3 var(--f-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
37:td.n{font:600 15px/1.3 var(--f-mono);font-variant-numeric:tabular-nums;text-align:right}
38:.chip{display:inline-block;font:500 11px/1 var(--f-mono);letter-spacing:.04em;padding:4px 7px;border-radius:3px;border:1px solid currentColor;white-space:nowrap}
40:.src{font:400 12px/1.4 var(--f-mono);color:var(--muted)}
45:.lbl{font:500 11px/1 var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
46:.closed li{color:var(--muted);font-size:14px}
47:.open li{font-size:15px}
49:.foot{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px;border-top:1px solid var(--line);padding-top:10px;font-size:14px}
50:.foot b{font-family:var(--f-mono);font-weight:500;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);display:block;margin-bottom:2px}
53:.order li::before{content:counter(o);font:600 22px/1 var(--f-display);color:var(--accent);text-align:right}
54:.order li span{font-size:14px;color:var(--muted);display:block}
57:@media (max-width:640px){.sys .cols{grid-template-columns:minmax(0,1fr)} h1{font-size:36px} h2{font-size:26px} .lead{font-size:16px}}
